async def act(page):
    """
    From the Dashboard, add the "XXXL" option to the global Size attribute so the product can use it.

    Approach:
    - Navigate (relative goto) to Manage Attributes index.
    - Find the "Size" attribute link and read its href, then navigate to that href with page.goto.
    - Add an option row (try several common Add button labels and fall back to scanning buttons whose text contains 'add' or '+').
    - Fill the last textbox on the page with 'XXXL' (heuristic for the new option input).
    - Click a Save button (try common names). The Save click is the final action because it may navigate away.

    Notes on knowledge-base functions: I inspected the available knowledge-base functions and there are none relevant to interacting with the Magento Admin UI for this task, so none are used.
    """
    import asyncio

    async def wait_for_ready(timeout=10000):
        try:
            await page.wait_for_load_state("networkidle", timeout=timeout)
        except Exception:
            # best-effort pause if networkidle isn't reached
            await asyncio.sleep(1)

    await wait_for_ready()

    # 1) Go to Manage Attributes (relative URL)
    try:
        await page.goto("/index.php/admin/catalog_product_attribute/index/")
        await wait_for_ready()
    except Exception:
        return

    # 2) Locate the Size attribute link and extract its href (try common casings)
    attr_href = None
    for attr_name in ["Size", "size", "SIZE"]:
        try:
            link = page.get_by_role("link", name=attr_name)
            href = await link.get_attribute("href")
            if href:
                attr_href = href
                break
        except Exception:
            continue

    if not attr_href:
        # Could not find Size attribute link; stop here.
        return

    # 3) Navigate to the attribute edit page via goto (rather than clicking the link)
    try:
        await page.goto(attr_href)
        await wait_for_ready()
    except Exception:
        return

    # 4) Click an Add Option / Add New button to add a new option row
    add_clicked = False
    add_button_names = ["Add Option", "Add New Option", "Add New", "Add", "Add Option Value"]
    for btn_name in add_button_names:
        try:
            await page.get_by_role("button", name=btn_name).click()
            await wait_for_ready()
            add_clicked = True
            break
        except Exception:
            continue

    # Fallback: scan buttons for visible text suggesting add
    if not add_clicked:
        try:
            btns = page.get_by_role("button")
            count = await btns.count()
            for i in range(count):
                try:
                    txt = await btns.nth(i).inner_text()
                except Exception:
                    txt = ""
                if txt and ("add" in txt.lower() or "+" in txt):
                    try:
                        await btns.nth(i).click()
                        await wait_for_ready()
                        add_clicked = True
                        break
                    except Exception:
                        continue
        except Exception:
            pass

    # 5) If an option row was likely added, fill the last textbox with 'XXXL'
    if add_clicked:
        try:
            textboxes = page.get_by_role("textbox")
            tb_count = await textboxes.count()
            if tb_count > 0:
                await textboxes.nth(tb_count - 1).fill("XXXL")
        except Exception:
            # best-effort only
            pass

    # 6) Save the attribute. Try common Save button names. This is the last action.
    for save_name in ["Save Attribute", "Save", "Save Options"]:
        try:
            await page.get_by_role("button", name=save_name).click()
            await wait_for_ready()
            return
        except Exception:
            continue

    # Final fallback: click a button whose text contains 'save' or 'submit', otherwise click first button.
    try:
        btns = page.get_by_role("button")
        cnt = await btns.count()
        for i in range(cnt):
            try:
                txt = await btns.nth(i).inner_text()
            except Exception:
                txt = ""
            if txt and ("save" in txt.lower() or "submit" in txt.lower()):
                try:
                    await btns.nth(i).click()
                    await wait_for_ready()
                    return
                except Exception:
                    continue
        if cnt > 0:
            try:
                await btns.nth(0).click()
                await wait_for_ready()
            except Exception:
                pass
    except Exception:
        pass

    return

